      'The concepts come together when a consumer asks for product 42. The client intends to read one product, so the contract tells it to send a GET request to /api/products/42 with any required headers, such as an authorization token and an Accept header. The client does not need to know which tables hold the product or which language implements the endpoint.',
      'The steps below describe a typical server path. Some systems insert gateways, caches or middleware between the network and application logic, and some handlers skip a separate data access layer. The point is the sequence of responsibilities: validate, apply rules, read data, build a response, interpret it.',
      'Notice that the API contract is the external interface throughout. The server may change its query, move the data or reimplement the handler, and the client’s code need not change as long as the request and response shapes stay as promised.',
