      'Latency names a delay across a stated interval; response time is client-observed with a stated boundary.',
      'Processing time, network round-trip time and TTFB each cover only part of a request timeline.',
      'Queueing can be a significant part of elapsed time without being application execution.',
      'There is no universal formula that ignores measurement boundaries or streaming behavior.',
