      'A shopper requests product details at GET /api/products/42. In a layered application, the request travels through responsibilities in a deliberate order and the result travels back through the same chain. The diagram in this lesson shows the same flow visually; the steps below state what each boundary contributes.',
      'Dependency direction describes who may call whom. In the common arrangement used here, presentation depends on business logic, and business logic depends on a data-access abstraction. The result returns upward. Some layered architectures permit only adjacent-layer calls, while others use different dependency arrangements or interfaces to invert a dependency. Do not claim that one universal rule applies to every layered system; state the rule chosen for the system you are discussing.',
