      'Order placement shows why controlled module interfaces matter. The Orders module receives a request from the presentation layer and validates its own rules: the customer exists, the basket is not empty and the order data is complete. To finish the operation it needs information and actions owned by other modules. It obtains them through defined operations rather than by opening their internal data stores.',
      'Communication can be synchronous and in-process when the caller needs an immediate answer. A module interface is still a boundary even though the call never leaves the process. For work that need not finish during the original request, an internal asynchronous message can be useful: the order module records the intent, and another module reacts later. That is an internal design choice, not a reason to introduce separately deployed infrastructure.',
