      'A complete network interaction needs both host location and application identity. Consider this illustrative endpoint pair: 192.168.1.20:51524 → 203.0.113.10:443 over TCP. The range 203.0.113.0/24 is reserved for documentation, so these addresses are teaching examples rather than a real store you should contact. The notation combines an IP address and a port with a colon.',
      'The destination tells us where the client wants to go: IP 203.0.113.10 and TCP port 443, the conventional HTTPS listening port. The source tells us where the reply should return: the client interface 192.168.1.20 and a client-chosen ephemeral port 51524. The transport protocol is part of the context because the port spaces differ between TCP and UDP.',
      'A TCP connection is not identified by an IP address alone, or even by a destination port alone. The classic four-tuple is source IP, source port, destination IP and destination port. Adding the transport protocol gives the full flow identity used by network devices. This is why two browser tabs on the same client can talk to the same server using different ephemeral source ports without their streams being confused.',
