      'For traditional HTTPS over HTTP/1.1 or HTTP/2, the browser opens a TCP connection to the server address on TCP port 443, completes the handshake, negotiates TLS, and then sends an HTTP request over the protected connection. For HTTP/3, the browser uses QUIC over UDP instead, so the traditional TCP handshake does not apply to that path. The application-level HTTPS goal is the same; the transport mechanics differ.',
