      'This is why network foundations matter in system design. An API endpoint is not just a URL; it maps to an address, a port and a transport. A database connection is not just a connection string; it uses a network path and protocol. A real-time feature is not just a WebSocket or stream; its transport choice determines what loss, ordering and retry behavior the application must handle.',
