    order: 12,
    title: 'Hybrid Communication Patterns',
    kind: 'process',
    paragraphs: [
      'Real systems rarely use only one pattern. A workflow can validate and accept a request synchronously, then defer independent work asynchronously. The user gets a fast, honest answer about what was accepted, while background components finish work that does not belong on the critical path.',
      'HTTP 202 Accepted is a useful conceptual signal for this style. It says the request was accepted for processing, not that processing is complete. A status URL lets the caller check progress later. The response body or Location header can point to that status resource, but the status itself must be backed by stored state.',
    ],
