      'Forward proxies support access control, filtering, logging and outbound policy enforcement.',
      'A proxy is not automatically an anonymity or privacy guarantee.',
      'HTTPS tunneling can prevent the proxy from reading application content.',
      'TLS interception requires additional trust and has privacy implications.',
      'The defining feature is which side configures and is represented by the proxy.',
