      'The distinction is architectural, not a property of a software package. Nginx can be configured as a forward proxy or a reverse proxy. The question is whose side the intermediary represents. A forward proxy is chosen and configured by clients or their network to manage outbound traffic. A reverse proxy is chosen and configured by a service operator to manage inbound traffic to backends.',
      'In a forward-proxy flow, an employee browser sends a request for an external site to the corporate proxy. The proxy applies policy, fetches the site and returns the response. The external site sees the proxy. In a reverse-proxy flow, an internet client opens the public application domain. The proxy selects an internal application server, forwards the request and returns the response. The client sees the public application, not the chosen instance.',
      'Visibility and security implications follow from that direction. A forward proxy can hide client addresses from destinations but gives the proxy operator visibility into employee browsing. A reverse proxy can hide backend topology from clients but gives the proxy operator visibility into incoming requests. Confusing the two leads to wrong configurations, such as expecting a public reverse proxy to filter employee browsing or expecting a corporate forward proxy to protect a public API.',
