    id: 'section-3-1-8',
    order: 8,
    title: 'Non-Relational Databases: The Core Idea',
    paragraphs: [
      'Non-relational databases are a family of data stores that do not require the application’s data to be organized primarily as normalized relational tables. Some store documents, some map keys to values, some organize wide rows, and some store graphs. They became useful when applications had data shapes, read patterns or scale requirements that made a table-first model less convenient.',
      'A non-relational design is often driven by access patterns. If most reads fetch one complete product aggregate by product identifier, a document can store that aggregate together. If the application only needs a session by token, a key-value lookup may be enough. If the important question is which users are connected to which other users, a graph model may express that directly. The model shapes how data is written so common reads stay simple.',
      'Non-relational does not mean no schema and does not mean no structure. A document store still contains fields and nested objects; a graph still has node and edge types; a wide-column store still has row and column organization. Some systems validate documents against rules, and application contracts remain necessary in every case. Product features vary, so each candidate must be evaluated rather than treated as a uniform category.',
    ],
    keyPoints: [
      'Non-relational databases are a diverse family, not one uniform design.',
      'Alternative models became useful for different data shapes and access patterns.',
      'A model can be chosen so common reads require little reconstruction.',
      'Flexible does not mean structureless or schema-free in practice.',
      'Document, key-value, wide-column and graph stores organize data differently.',
      'Application contracts and validation still matter with flexible storage.',
      'Evaluate the specific system and workload instead of the NoSQL label.',
    ],
