      'A key-value store maps a key to a value and is commonly queried by that key. Redis is a familiar example used for caches and session-like data where fast lookup dominates. The trade-off is limited query flexibility: if the application needs to search inside values or join information, a key-value store is usually not the right primary model. A wide-column store organizes rows with flexible column families and is designed for particular large-scale distributed access patterns; Apache Cassandra is a common example. It can handle large volumes but asks designers to understand partition and query patterns carefully.',
      'A graph database represents entities as nodes and relationships as edges. Neo4j is a familiar example. Queries traverse edges, which is useful when connections such as friend relationships or purchase paths are central. The trade-off is that graph storage is not automatically better for simple aggregates or tabular reporting. These categories are introductions only; later modules examine them in more depth.',
