      'A simplified product document can hold an identifier, name, price, category and an attributes object. The category field is a nested object with its own identifier and name. The attributes object can contain a keyboard layout, switch type and wireless flag. Related information that is usually read with the product is embedded in the same document rather than assembled from several tables.',
      'This structure is useful when categories need different attributes. A mechanical keyboard and a desk lamp do not need the same columns. A document store can keep layout and switchType for one product and entirely different fields for another without a shared table with many empty columns. Retrieval is often a lookup by product identifier followed by reading the complete aggregate.',
      'Embedding versus referencing is a design decision. Embedding simplifies reads because the needed data travels with the document, but it can duplicate shared data and make updates more complex. Referencing avoids some duplication but requires another lookup or application-side assembly. This lesson only introduces the trade-off; detailed document schema design is left to later modules.',
