      'Schema design is a repeatable reasoning process rather than a scramble for table names. Work from requirements to entities, then keys, relationships, constraints and dependencies. Review access patterns after the logical structure is sound so performance concerns do not justify duplication before the facts have owners.',
      'The challenge after this section asks you to apply the same workflow to a university enrollment database. There is more than one correct schema, but every defensible answer must explain cardinality, keys, constraints, anomalies and normal form decisions. Use the checklist below to review your work before reading or writing a solution.',
      'Common schema design mistakes include putting a foreign key on the one side of a one-to-many relationship, using FLOAT for currency, assuming a single-column primary key makes a table fully normalized, storing a list of identifiers in one column and treating sample data as proof of a business rule. Also avoid cascading deletes without checking history requirements, calling every extra table normalization and denormalizing by default.',
