      'Joins combine rows from tables using a relationship. Their cost depends on the number of rows entering the join, the width of those rows, available indexes and the distribution of join keys. A join that is trivial with a few hundred rows can dominate a plan when millions of rows reach it.',
      'Nested Loops reads rows from one input and probes the other for matches. It can be very fast when the outer input is small and the inner input has a useful index. If the outer input grows large or each probe becomes expensive, the same strategy can degrade. Nested Loops is common in selective lookups.',
      'Hash Match builds a hash table from one input and probes it with the other. It often suits larger joins where no efficient ordered path exists, but it uses memory and can spill to temporary storage when the build side is underestimated. Merge Join reads two ordered inputs and can be efficient when both sides are already sorted or appropriately indexed.',
      'Indexing join columns can help probe-based and ordered strategies. Filtering early, when it preserves the same result, reduces the rows entering a join and often helps more than forcing a join type. Good cardinality estimates matter because the optimizer chooses algorithms based on expected row counts.',
