      'Sorting requires arranging rows before they can be returned or fed into another operator. It consumes CPU and memory and may spill to disk for large result sets. An index whose key order matches ORDER BY can sometimes avoid a separate Sort, especially when filtering and ordering use compatible leading columns.',
      'Projecting unnecessary columns increases work at every later stage. SELECT * pulls wide rows into intermediate operators, consumes more memory and network bandwidth, and can prevent a covering index from being useful. Requesting only the columns the endpoint needs is a simple, low-risk improvement that also makes contracts clearer.',
      'Offset pagination with ORDER BY and OFFSET/FETCH needs deterministic ordering. Without a unique tie-breaker, rows with equal sort keys can appear in different positions between requests. Large offsets also require the engine to skip an increasing number of rows, so deep pages can become progressively more expensive.',
      'Keyset pagination avoids large offsets by remembering the last seen sort key and asking for rows after it, for example orders older than the last CreatedAt and OrderId seen. It needs a stable, indexed ordering and careful handling of ties, but it often scales better for infinite scroll and API feeds.',
      'Application access patterns matter too. The N+1 query problem occurs when code runs one query to fetch a list and then another query for each item, such as loading a customer separately for every order. Batching, joining or explicitly loading related data can remove hundreds of round trips. Reducing database round trips is part of performance work even when each individual query is fast.',
