    id: 'challenge-3-1',
    title: 'Choose a Database Architecture for an E-Commerce Platform',
    scenario:
      'An e-commerce platform stores customers, orders, payments, products, product attributes, user sessions and product browsing activity. Orders and payments require reliable relationships and correctness across several records. Product attributes vary significantly between categories. User sessions require fast lookup by token. Product browsing activity grows rapidly and is mostly written, with aggregate reporting queried later. The team wants to keep infrastructure manageable and must justify every storage technology it introduces.',
