      'Evaluate whether session data fits a key-value model and state its durability expectations.',
      'Explain how rapidly growing browsing activity could be stored and how it would be queried.',
      'Decide whether polyglot persistence is justified for this platform and explain what evidence would change the decision.',
      'Identify consistency and synchronization concerns created by duplicated product or customer data.',
