      'A relationship map showing cardinality between customers, orders, payments and products.',
      'A model decision table covering relational, document, key-value and activity-storage choices with alternatives.',
      'A consistency and synchronization section naming duplicated data and how staleness will be handled.',
      'An operations section covering backup, monitoring, upgrades and skills for every chosen technology.',
      'A recommended initial architecture with reasons for each choice and a description of possible future changes.',
      'A detailed model solution and evaluation criteria that accept more than one architecture when assumptions are justified.',
