      'A relationship map naming cardinality and foreign key placement in both directions.',
      'A junction table design for enrollments with its key and relationship attributes.',
      'A constraint table covering NOT NULL, UNIQUE, CHECK, DEFAULT and referential actions.',
      'A short anomaly analysis with one insertion, one update and one deletion example.',
      'A functional dependency list with full, partial and transitive cases labeled.',
      'A 1NF, 2NF and 3NF justification tied to specific tables and dependencies.',
      'A coherent final relational schema that represents students, courses, instructors, departments, enrollments and grades.',
      'A denormalization section naming any intentional copy, its owner, refresh rule and acceptable staleness.',
      'A detailed model solution and evaluation criteria that accept more than one defensible design.',
