      'Model solution step 2 — Types: use INT or BIGINT surrogate identifiers, NVARCHAR for names and codes, DATE for enrollment dates, DECIMAL for exact graded scores if numeric grades are required, and NVARCHAR(2) for letter grades. EnrollmentDate should not be DATETIME2 unless a time component is required.',
      'Model solution step 3 — Keys: DepartmentID, InstructorID, CourseID and StudentID are stable primary keys. DepartmentName, InstructorEmail, StudentEmail and CourseCode are candidate keys that should be enforced with UNIQUE.',
      'Model solution step 4 — One-to-many: a department has many instructors and many courses, so Instructors.DepartmentID and Courses.DepartmentID are foreign keys. A student has many enrollments and a course has many enrollments, so both identifiers appear in the enrollment table.',
      'Model solution step 5 — Many-to-many: StudentCourses with primary key (StudentID, CourseID) is a valid junction table when a student enrolls once in a course. EnrollmentDate, Status and Grade belong there because they describe the enrollment. If retakes in different terms are allowed, add TermID to the key or use EnrollmentID plus a UNIQUE business rule.',
      'Model solution step 6 — Optional one-to-one: an optional InstructorProfiles table keyed by InstructorID can hold office, biography and contact details when that data is rarely read, governed differently or created later. Putting those columns in Instructors is also valid when they are small and always read together.',
      'Model solution step 7 — Instructor assignment: Courses.InstructorID is a one-to-many design when each course has one instructor. If team teaching is allowed, use CourseInstructors(CourseID, InstructorID) as a second junction table and move instructor information out of Courses.',
      'Model solution step 8 — Constraints: require names, emails and codes with NOT NULL; enforce unique emails, course codes and department names with UNIQUE; check Credits BETWEEN 1 AND 12, Status IN (Enrolled, Completed, Withdrawn) and Grade IN (A, B, C, D, F) or NULL; default EnrollmentDate to the current date and Status to Enrolled. Use NO ACTION for deletes when academic history must be preserved.',
      'Model solution step 9 — Anomalies: a new course cannot be inserted without a student in the original table; a department rename must be repeated across many rows and can be applied inconsistently; deleting the last enrollment for a course removes the only course description.',
      'Model solution step 10 — Functional dependencies: StudentID determines StudentName and StudentEmail; CourseID determines CourseCode, Title, Credits and DepartmentID; InstructorID determines InstructorName, Email and DepartmentID; DepartmentID determines DepartmentName; (StudentID, CourseID) determines EnrollmentDate, Status and Grade. StudentID determining StudentName inside an enrollment keyed by (StudentID, CourseID) is partial; CourseID determining DepartmentName through DepartmentID is transitive.',
      'Model solution step 11 — Normal forms: one row per enrollment field value removes repeating groups for 1NF. Students, Courses and Instructors hold facts that depend on only part of the enrollment key for 2NF. Departments holds DepartmentName so it is not reached through DepartmentID inside Courses or Instructors for 3NF.',
      'Model solution step 12 — Justified duplication: a transcript snapshot may copy course titles and grades at completion time, and a reporting table may cache enrollment counts. Treat source records as authoritative, document the refresh process and accept a stated staleness window. Never let a cache become the only copy of a current student, course or grade fact.',
      'Evaluation criteria: award correctness for entity boundaries, relationship cardinality and foreign key placement; for stable and unique keys; for constraints that match stated business rules; for accurate anomaly and dependency analysis; and for a defensible 1NF to 3NF explanation. Accept alternative designs when assumptions are explicit, such as term-based keys, separate profiles or a course-instructor junction table.',
